arguments.keystrokes:
cat << 'EOF' > /tmp/gen_policy.py
import json

policy = {
  "schema_version": 1,
  "mode": "enforce",
  "limits": {
    "max_body_bytes": 2097152,
    "max_fields": 256,
    "max_json_depth": 32,
    "max_values_per_rule": 16
  },
  "failure_handling": {
    "parse_error": "reject",
    "decode_error": "reject",
    "oversize": "reject",
    "status": 400
  },
  "audit": {
    "enabled": True,
    "event": "edge.denial",
    "fields": ["request_id", "rule_id", "method", "route", "source", "field", "reason"],
    "redact_values": True
  },
  "rules": [
    {
      "id": "interactive-query",
      "priority": 10,
      "match": {
        "methods": ["POST"],
        "routes": ["/v1/render"]
      },
      "selectors": [
        {"location": "query", "names": ["template", "view"]}
      ],
      "transforms": ["percent_decode", "percent_decode", "unicode_nfkc", "backslash_to_slash", "trim_ascii"],
      "predicate": {"op": "locator_outside", "allowed_schemes": ["asset"]},
      "action": {"type": "block", "status": 403}
    },
    {
      "id": "interactive-form",
      "priority": 20,
      "match": {
        "methods": ["POST"],
        "routes": ["/v1/render"]
      },
      "selectors": [
        {"location": "form", "names": ["template", "options.template"]}
      ],
      "transforms": ["percent_decode", "percent_decode", "unicode_nfkc", "backslash_to_slash", "trim_ascii"],
      "predicate": {"op": "locator_outside", "allowed_schemes": ["asset"]},
      "action": {"type": "block", "status": 403}
    },
    {
      "id": "interactive-json",
      "priority": 30,
      "match": {
        "methods": ["POST"],
        "routes": ["/v1/render"]
      },
      "selectors": [
        {"location": "json", "pointers": ["/template", "/options/template"]}
      ],
      "transforms": ["percent_decode", "unicode_nfkc", "backslash_to_slash", "trim_ascii"],
      "predicate": {"op": "locator_outside", "allowed_schemes": ["asset"]},
      "action": {"type": "block", "status": 403}
    },
    {
      "id": "interactive-multipart",
      "priority": 40,
      "match": {
        "methods": ["POST"],
        "routes": ["/v1/render"]
      },
      "selectors": [
        {"location": "multipart", "names": ["template_locator"]}
      ],
      "transforms": ["percent_decode", "unicode_nfkc", "backslash_to_slash", "trim_ascii"],
      "predicate": {"op": "locator_outside", "allowed_schemes": ["asset"]},
      "action": {"type": "block", "status": 403}
    },
    {
      "id": "interactive-header",
      "priority": 50,
      "match": {
        "methods": ["POST"],
        "routes": ["/v1/render"],
        "headers": [{"name": "X-Integration-Mode", "equals": "legacy", "case_sensitive": False}]
      },
      "selectors": [
        {"location": "header", "names": ["X-Legacy-Template"]}
      ],
      "transforms": ["percent_decode", "unicode_nfkc", "backslash_to_slash", "trim_ascii"],
      "predicate": {"op": "locator_outside", "allowed_schemes": ["asset"]},
      "action": {"type": "block", "status": 403}
    },
    {
      "id": "batch-json",
      "priority": 60,
      "match": {
        "methods": ["POST"],
        "routes": ["/v1/render/batch"]
      },
      "selectors": [
        {"location": "json", "pointers": ["/jobs/*/template", "/jobs/*/options/template"]}
      ],
      "transforms": ["percent_decode", "unicode_nfkc", "backslash_to_slash", "trim_ascii"],
      "predicate": {"op": "locator_outside", "allowed_schemes": ["asset"]},
      "action": {"type": "block", "status": 403}
    },
    {
      "id": "validation-query",
      "priority": 70,
      "match": {
        "methods": ["PUT"],
        "routes": ["/v1/templates/validate"]
      },
      "selectors": [
        {"location": "query", "names": ["locator"]}
      ],
      "transforms": ["percent_decode", "percent_decode", "unicode_nfkc", "backslash_to_slash", "trim_ascii"],
      "predicate": {"op": "locator_outside", "allowed_schemes": ["asset"]},
      "action": {"type": "block", "status": 403}
    },
    {
      "id": "validation-form",
      "priority": 80,
      "match": {
        "methods": ["PUT"],
        "routes": ["/v1/templates/validate"]
      },
      "selectors": [
        {"location": "form", "names": ["locator"]}
      ],
      "transforms": ["percent_decode", "percent_decode", "unicode_nfkc", "backslash_to_slash", "trim_ascii"],
      "predicate": {"op": "locator_outside", "allowed_schemes": ["asset"]},
      "action": {"type": "block", "status": 403}
    },
    {
      "id": "validation-json",
      "priority": 90,
      "match": {
        "methods": ["PUT"],
        "routes": ["/v1/templates/validate"]
      },
      "selectors": [
        {"location": "json", "pointers": ["/locator"]}
      ],
      "transforms": ["percent_decode", "unicode_nfkc", "backslash_to_slash", "trim_ascii"],
      "predicate": {"op": "locator_outside", "allowed_schemes": ["asset"]},
      "action": {"type": "block", "status": 403}
    }
  ]
}

with open('/app/edge-policy.json', 'w') as f:
    json.dump(policy, f, indent=2)
EOF
